INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Ich war noch nie von einer Creme so überzeugt! Habe auch wirklich schon etliche probiert, auch sehr teuere. Ich habe eine schwierige Haut mit Rosacea, Pigmentflecken etc. Diese Creme beruhigt und ist so angenehm auf der Haut, ich möchte keine andere mehr! Verbesserungsvorschläge wären nur: 1. würde gerne ein Abo abschließen können, dass ich „meine“ Creme z.B. alle 3 Monate automatisch zugeschickt bekomme 😁👍🏻 und 2. zwecks dem Umweltgedanken vll nur Sachen zum nachfüllen schicken, wenn man schon ein Glasfläschchen aus der ersten Bestellung zu Hause hat, das wäre top! ☺️👍🏻', 'Laura Rösel', 'laura.roesel@gmx.de', 'approved', '2024-07-30 03:17:03', 0, 0);
