INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('serum', 5, 'Gute Bewertung', 'Ich bin sehr zufrieden mit dem System.  Was ich schade finde ist, dass ich die aufwendige Verpackung nicht wiederverwerten kann. Ansonsten stimmt alles bei mir. Was noch fehlt, ist eine Abdeckung mit Lichtschutzfaktor, ich habe allerdings ein Produkt eines anderen Herstellers gefunden, welches gut  passt.', 'Natalie', 'higichabo@hotmail.de', 'approved', '2024-07-10 14:33:17', 0, 0);